# ------------------------------------------------------------ 4. replication
def ginzu(rev0=21285., g1=.0225, g25=.031, m1=.205, mt=.213, conv=5, s2c=2.2, teff=.235, tm=.25, w0=.0834, wst=.0843, gst=.03, roic=.20,
          debt=8282., mi=352., cash=1612., nonop=82., opt=439., sh=797.9):
    """The Valuation output sheet of fcffsimpleginzu.xlsx with its default switches (one-year reinvestment lag,
    tax rate moving to the marginal rate by year 10, cost of capital moving to the stable rate over years 6-10)."""
    g = [None, g1] + [g25] * 4 + [g25 - (g25 - gst) / 5 * k for k in range(1, 6)] + [gst]
    r = [rev0]
    for y in range(1, 12): r.append(r[-1] * (1 + g[y]))
    mg = [None, m1] + [mt if y > conv else mt - ((mt - m1) / conv) * (conv - y) for y in range(2, 11)]; mg.append(mg[10])
    tx = [None] + [teff] * 5 + [teff + (tm - teff) / 5 * k for k in range(1, 6)] + [tm]
    w = [None] + [w0] * 5 + [w0 - (w0 - wst) / 5 * k for k in range(1, 6)]
    df = 1.0; pv = 0.0; out = []
    for y in range(1, 11):
        eb = r[y] * mg[y]; nop = eb * (1 - tx[y]); re_ = (r[y + 1] - r[y]) / s2c; f = nop - re_; df /= (1 + w[y]); pv += f * df
        out.append((y, g[y], r[y], mg[y], eb, tx[y], nop, re_, f, w[y], df, f * df))
    nop11 = r[11] * mg[11] * (1 - tm); rs = roic if roic else wst
    tcf = nop11 * (1 - gst / rs); tv = tcf / (wst - gst); pvtv = tv * df
    ops = pv + pvtv; eq = ops - debt - mi + cash + nonop
    return dict(rows=out, pv=pv, nop11=nop11, tcf=tcf, tv=tv, pvtv=pvtv, ops=ops, eq=eq, v=(eq - opt) / sh, rev11=r[11])

