def solve(f, lo, hi):
    for _ in range(80):
        mid = (lo + hi) / 2
        if f(mid) < price: lo = mid
        else: hi = mid
    return (lo + hi) / 2
need_m = solve(lambda x: ginzu(mt=x)["v"], .2, .5)
need_g = solve(lambda x: ginzu(gst=x)["v"], .03, .08)
need_g25 = solve(lambda x: ginzu(g25=x)["v"], .03, .30)
need_w = solve(lambda x: -ginzu(w0=x, wst=x)["v"] + 2 * price, .04, .0834)
print(f"\nWhat the $98.71 price requires, changing one input at a time and holding the rest of the base case: a target operating margin of {pct(need_m, 1)} from year 5 on (against 21.3%); or growth in perpetuity of {pct(need_g)} (against 3%, and above the 4.82% riskfree rate); or revenue growth of {pct(need_g25, 1)} a year in years 2 to 5 (against 3.1%); or a cost of capital of {pct(need_w)} in every year including the stable period (against 8.34% and 8.43%). With the published consensus margins and growth in perpetuity at 4.82% together the value is ${ginzu(m1=.212, mt=.22, gst=.0482)['v']:.2f}.\n")

