def ols(xs, ys):
    n = len(xs); mx, my = sum(xs) / n, sum(ys) / n
    sxx = sum((x - mx) ** 2 for x in xs); sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    b1 = sxy / sxx; a = my - b1 * mx
    sse = sum((y - a - b1 * x) ** 2 for x, y in zip(xs, ys)); sst = sum((y - my) ** 2 for y in ys)
    se_b = (sse / (n - 2) / sxx) ** 0.5; s_e = (sse / (n - 2)) ** 0.5
    return a, b1, 1 - sse / sst, se_b, s_e, n
